const t=key=>(copy[window.tenantI18n?.language]||copy.en)[key]||key;
const operatorDataAllowed=()=>!!profile&&profile.integrations?.some(row=>row.provider==='beinsystems_operator')&&(profile.member?.role==='owner'||(profile.member?.permissions||[]).some(value=>value==='operator_data'||value==='operator_data:view'));
const operatorLinkAllowed=()=>!!profile&&(profile.member?.role==='owner'||(profile.member?.permissions||[]).some(value=>value==='operator_data'||value==='operator_data:link'));
let profile=null,profileKey='',paused=true,epoch=0,listRevision=0,cardRevision=0,formRevision=0,page=null,readState='idle',readError='',source='',query='',offset=0,limit=50,flight=null,loadedKey='',loadedAt=0,debounce=null,card=null,formState=null,navigating=false,lastRoute='',message='',routeRevision=0,accessProof=null,bindingError=false;
const identity=data=>data?.member?String(data.member.tenant_id)+':'+String(data.member.telegram_id):'';
// Profile consumers expose integrations as either records or a provider-keyed
// map. Normalize only the Kommo comparison data; listing flags remain authority.
function kommoMetadata(value){
 const record=item=>item!==null&&typeof item==='object'&&!Array.isArray(item);
 if(Array.isArray(value))return value.filter(item=>record(item)&&item.provider==='kommo').map(item=>({provider:'kommo',...item}));
 if(!record(value))return [];
 return Object.entries(value).filter(([provider,item])=>provider==='kommo'||record(item)&&item.provider==='kommo').map(([,item])=>record(item)?{provider:'kommo',...item}:{provider:'kommo',value:item});
}
const fingerprint=data=>JSON.stringify([identity(data),data?.member?.active,data?.member?.role,[...(Array.isArray(data?.member?.permissions)?data.member.permissions:[])].sort(),data?.capabilities?.modules?.customers,data?.capabilities?.modules?.deals,data?.capabilities?.pipeline_scope,data?.capabilities?.deal_board,data?.member?.workflow,kommoMetadata(data?.integrations)]);
const active=()=>!paused&&!accessProof&&profile?.member?.active===true;
const visible=()=>view.classList.contains('active');
const scope=()=>({epoch,owner:identity(profile),tenant:String(profile?.member?.tenant_id||''),user:String(profile?.member?.telegram_id||'')});
const current=s=>s.epoch===epoch&&s.owner===identity(profile)&&active();
function scopedURL(path,s){const url=new URL(path,location.origin);url.searchParams.set('expected_tenant_id',s.tenant);url.searchParams.set('expected_user_id',s.user);return url.pathname+url.search}
async function api(path,options={},s=scope()){
 if(!current(s)){const error=Error('Contact scope changed');error.stale=true;throw error}
 const response=await fetch(scopedURL(path,s),{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
 let data;try{data=await response.json()}catch(_){const error=Error('Unparseable contact response');error.status=response.status;error.unknown=true;throw error}
 if(!current(s)){const error=Error('Contact scope changed');error.stale=true;throw error}
 if(!response.ok||data?.success!==true){const error=Error(data?.error||'Contact request failed');error.status=response.status;error.unknown=response.ok;error.code=data?.code||data?.error;error.payload=data;throw error}return data;
}
async function renderOperatorContactLinks(token){
 const panel=$('nativeEntityBody')?.querySelector('[data-contact-panel="operator"]');
 if(!panel||!operatorDataAllowed()||!cardCurrent(token))return;
 panel.replaceChildren();const heading=document.createElement('h3'),status=document.createElement('p'),content=document.createElement('div');heading.textContent='BeinSystems Operator';status.setAttribute('role','status');status.textContent='Загружаем подтверждённые связи Operator…';panel.append(heading,status,content);
 try{
  const url=new URLSearchParams({entity_type:'contact',entity_id:token.row.id});
  const links=await api('/api/platform/operator/links?'+url.toString(),{},token.scope);if(!cardCurrent(token))return;
  const companyId=String(token.row.company_id||'');
  if(!companyId){status.textContent='Сначала свяжите CRM-контакт с CRM-компанией и подтвердите аккаунт компании в Operator.';return;}
  const companyQuery=new URLSearchParams({entity_type:'company',entity_id:companyId});
  const companyLinks=await api('/api/platform/operator/links?'+companyQuery.toString(),{},token.scope);if(!cardCurrent(token))return;
  const accounts=(companyLinks.links||[]).filter(item=>item.status==='confirmed'&&item.external_type==='account');
  for(const item of links.links||[]){if(item.external_type==='profile_user'&&item.status==='confirmed'){const row=document.createElement('p');row.textContent='ERP-пользователь: '+item.external_id+' · account: '+item.scope_id;content.append(row);if(operatorLinkAllowed()){const revoke=document.createElement('button');revoke.type='button';revoke.textContent='Отозвать связь';revoke.onclick=async()=>{if(!confirm('Отозвать подтверждённую связь?'))return;try{await api('/api/platform/operator/links/'+encodeURIComponent(item.id)+'/revoke',{method:'POST',body:JSON.stringify({expected_tenant_id:token.scope.tenant,expected_user_id:token.scope.user})},token.scope);if(cardCurrent(token))void renderOperatorContactLinks(token);}catch(error){if(cardCurrent(token))status.textContent=error.message;}};content.append(revoke);}}}
  if(!accounts.length){status.textContent='У CRM-компании нет подтверждённого аккаунта Operator.';return;}
  for(const account of accounts){
   const row=document.createElement('section'),label=document.createElement('p'),show=document.createElement('button'),users=document.createElement('button'),list=document.createElement('div');let selectedLogin='';
   label.textContent='Аккаунт Operator: '+account.external_id;show.type=users.type='button';show.textContent='Профиль аккаунта';users.textContent='Пользователи аккаунта';row.append(label,show,users,list);content.append(row);
   show.onclick=async()=>{show.disabled=true;try{const result=await api('/api/platform/operator/account-info',{method:'POST',body:JSON.stringify({entity_type:'company',entity_id:companyId,account:account.external_id,expected_tenant_id:token.scope.tenant,expected_user_id:token.scope.user})},token.scope);if(!cardCurrent(token))return;label.textContent='Аккаунт Operator: '+result.account_info.account+(result.account_info.last_contact?' · Последний контакт: '+result.account_info.last_contact:'')+(result.account_info.partner_name?' · Partner: '+result.account_info.partner_name:'');}catch(error){if(cardCurrent(token))status.textContent=error.message;}finally{show.disabled=false;}};
   const evidence=document.createElement('input'),confirmButton=document.createElement('button');
   if(operatorLinkAllowed()){
    evidence.placeholder='Основание ручной проверки';confirmButton.type='button';confirmButton.textContent='Подтвердить выбранного ERP-пользователя';confirmButton.disabled=true;row.append(evidence,confirmButton);
   }
   users.onclick=async()=>{users.disabled=true;selectedLogin='';if(operatorLinkAllowed())confirmButton.disabled=true;try{const result=await api('/api/platform/operator/profile-users',{method:'POST',body:JSON.stringify({entity_type:'company',entity_id:companyId,account:account.external_id,expected_tenant_id:token.scope.tenant,expected_user_id:token.scope.user})},token.scope);if(!cardCurrent(token))return;list.replaceChildren();for(const user of result.users||[]){const choose=document.createElement('button');choose.type='button';choose.textContent='Выбрать login: '+user.login;choose.disabled=user.bindable!==true;choose.onclick=()=>{selectedLogin=user.login;for(const node of list.querySelectorAll('button'))node.setAttribute('aria-pressed',String(node===choose));if(operatorLinkAllowed())confirmButton.disabled=false;};list.append(choose);}if(!(result.users||[]).length)list.textContent='Пользователи не найдены.';}catch(error){if(cardCurrent(token))status.textContent=error.message;}finally{users.disabled=false;}};
   if(operatorLinkAllowed())confirmButton.onclick=async()=>{if(!selectedLogin||evidence.value.trim().length<8){status.textContent='Загрузите пользователей аккаунта, выберите login и укажите основание проверки.';return;}confirmButton.disabled=true;try{await api('/api/platform/operator/links',{method:'POST',body:JSON.stringify({entity_type:'contact',entity_id:token.row.id,account:account.external_id,login:selectedLogin,evidence:evidence.value.trim(),expected_tenant_id:token.scope.tenant,expected_user_id:token.scope.user})},token.scope);if(cardCurrent(token))void renderOperatorContactLinks(token);}catch(error){if(cardCurrent(token))status.textContent=error.message;}finally{confirmButton.disabled=false;}};
  }
  status.textContent='';
 }catch(error){if(cardCurrent(token))status.textContent=error.message;}
}
function ownedCard(){const modal=$('nativeEntityCard');return !!modal&&!!card&&modal.dataset.contactsDirectoryOwner===String(card.revision)}
function formCurrent(state){return state===formState&&state.revision===formRevision&&current(state.scope)&&$('nativeContactModal').classList.contains('show')}
function resetForm(){window.tenantCrmSaveReceipt?.clear('nativeContactSyncReceipt');const form=$('nativeContactForm');form.reset();$('nativeContactId').value='';$('nativeContactCompany').replaceChildren();form.dataset.dirty='false';form.querySelectorAll('input,select,button').forEach(node=>{node.disabled=false;if('readOnly'in node)node.readOnly=false});$('nativeContactModalError').textContent='';$('contactsCheckSave')?.remove();$('contactsCompanyPermission')?.remove()}
function clearOwned(){window.tenantCrmSaveReceipt?.clear('contactsSyncReceipt');bindingError=false;accessProof=null;curtain(false);routeRevision++;epoch++;listRevision++;cardRevision++;formRevision++;clearTimeout(debounce);flight=null;page=null;loadedKey='';loadedAt=0;readState='idle';readError='';message='';$('customersList').replaceChildren();$('customersNotice').textContent='';$('customerCount').textContent=t('checking');if(ownedCard()){const modal=$('nativeEntityCard');modal.classList.remove('show');$('nativeEntityBody').replaceChildren();$('nativeEntityTitle').textContent='';delete modal.dataset.contactsDirectoryOwner}card=null;formState=null;$('nativeContactModal').classList.remove('show');resetForm();$('customerSearch').value='';render();}
function translate(){
 $('contactsTitle').textContent=t('title');$('contactsSourceTitle').textContent=t('source');$('contactsSource').options[0].textContent=t('native');$('contactsSource').options[1].textContent=t('kommo');$('customerSearch').placeholder=t('search');$('customerSearch').setAttribute('aria-label',t('search'));$('customersRefresh').querySelector('span').textContent=t('refresh');$('nativeContactCreate').textContent=t('create');$('contactsPrevious').textContent=t('previous');$('contactsNext').textContent=t('next');
 const labels={nativeContactName:'name',nativeContactPhone:'phone',nativeContactEmail:'email',nativeContactCompany:'company'};for(const [id,key]of Object.entries(labels)){const label=$(id).closest('label');if(label?.firstChild?.nodeType===3)label.firstChild.textContent=t(key)}
 $('nativeContactModal').querySelectorAll('[data-crm-close]').forEach(button=>{if(!button.classList.contains('close'))button.textContent=t('cancel');button.setAttribute('aria-label',t('close'))});$('nativeContactForm').querySelector('[type=submit]').textContent=formState?.phase==='contact_saved'?t('assign'):t('save');$('nativeContactModalTitle').textContent=t(formState?.mode==='edit'?'edit':'create');
}
