/* A source key is unique only inside its selected company. Binding is an
   intent restriction; it never supplies authority or switches workspaces. */
function bindingProblem(url=new URL(location.href)){
 const values=url.searchParams.getAll('contacts_tenant'),historyValue=history.state?.contactsTenant;
 if(values.length&&(values.length!==1||!uuid(values[0])))return true;
 if(historyValue!==undefined&&(!uuid(historyValue)||values.length&&historyValue.toLowerCase()!==values[0].toLowerCase()))return true;
 const tenant=String(profile?.member?.tenant_id||'').toLowerCase();
 return !!(values.length&&values[0].toLowerCase()!==tenant||historyValue!==undefined&&historyValue.toLowerCase()!==tenant);
}
function checkBinding(){
 if(!bindingProblem()){bindingError=false;return true}
 bindingError=true;routeRevision++;listRevision++;flight=null;page=null;loadedKey='';readState='error';readError=t('bindingMessage');
 if(ownedCard()){$('nativeEntityCard').classList.remove('show');$('nativeEntityBody').replaceChildren();$('nativeEntityTitle').textContent='';delete $('nativeEntityCard').dataset.contactsDirectoryOwner;card=null;cardRevision++}
 render();return false;
}
function clearContactSelection(selectedLegacy){
 const url=new URL(location.href),contactRoute=url.searchParams.get('view')==='customers';
 const ownLegacy=contactRoute||url.searchParams.get('view')!=='deals'&&(url.searchParams.has('contacts_tenant')||!!selectedLegacy&&url.searchParams.get('deal_id')===selectedLegacy);
 for(const key of ['contacts_source','contacts_search','contacts_offset','contact_id','contacts_entry','contacts_tenant'])url.searchParams.delete(key);
 if(ownLegacy)url.searchParams.delete('deal_id');
 const state={...history.state,contactsCard:false,contacts:null};delete state.contactsTenant;history.replaceState(state,'',url);
 source='';query='';offset=0;
}
function routeState(){const p=new URL(location.href).searchParams;return {source:['native','kommo'].includes(p.get('contacts_source'))?p.get('contacts_source'):'',query:(p.get('contacts_search')||'').slice(0,120),offset:/^\d+$/.test(p.get('contacts_offset')||'')?Number(p.get('contacts_offset')):0,native:p.get('contact_id'),entry:p.get('contacts_entry'),legacy:p.get('deal_id')}}
function listURL(push=false){if(!checkBinding())return false;const url=new URL(location.href);url.searchParams.set('view','customers');if(source)url.searchParams.set('contacts_source',source);else url.searchParams.delete('contacts_source');if(query)url.searchParams.set('contacts_search',query);else url.searchParams.delete('contacts_search');if(offset)url.searchParams.set('contacts_offset',String(offset));else url.searchParams.delete('contacts_offset');const state={...history.state,view:'customers',contacts:{source,query,offset,scroll:window.scrollY||0}};history[push?'pushState':'replaceState'](state,'',url);return true}
function writeCardRoute(row,legacyDealId){if(!checkBinding()||visible()&&!listURL())return false;const url=new URL(location.href);for(const key of ['contact_id','contacts_entry','deal_id'])url.searchParams.delete(key);url.searchParams.set('view','customers');url.searchParams.set('contacts_tenant',String(profile.member.tenant_id).toLowerCase());if(source)url.searchParams.set('contacts_source',source);if(query)url.searchParams.set('contacts_search',query);if(offset)url.searchParams.set('contacts_offset',String(offset));if(row.kind==='native_contact')url.searchParams.set('contact_id',row.id);else if(legacyDealId)url.searchParams.set('deal_id',legacyDealId);else url.searchParams.set('contacts_entry',row.key);navigating=true;history.pushState({...history.state,view:'customers',contactsCard:true,contactsTenant:String(profile.member.tenant_id).toLowerCase()},'',url);window.tenantAppNavigate?.('customers',false);navigating=false;return true;}
function listingPath(extra={}){const params=new URLSearchParams({listing:'1',limit:String(limit),offset:String(offset),...extra});if(source&&!params.has('source'))params.set('source',source);if(query&&!params.has('search'))params.set('search',query);return '/api/platform/crm/native/contacts?'+params}
async function refresh(value,force=false){if(active()&&visible()&&!checkBinding())return false;if(value!==undefined&&String(value)!==query){query=String(value).slice(0,120);offset=0}if(!active()||!visible())return false;const s=scope(),key=JSON.stringify([s.epoch,s.owner,source,query,offset]);if(flight?.key===key)return flight.promise;if(!force&&page&&key===loadedKey&&Date.now()-loadedAt<30000){render();return true}const revision=++listRevision,token={key,promise:null};readState='loading';readError='';render();token.promise=(async()=>{try{const data=await api(listingPath(),{},s);if(!current(s)||revision!==listRevision||!visible()||!checkBinding())return false;if(!Array.isArray(data.data)||!Array.isArray(data.sources)||!['native','kommo'].includes(data.source)||!Number.isInteger(data.total))throw Error('Invalid directory response');page=data;source=data.source;offset=data.offset;limit=data.limit;readState='ready';loadedKey=JSON.stringify([s.epoch,s.owner,source,query,offset]);loadedAt=Date.now();if(!listURL())return false;render();return true}catch(error){if(error.stale||!current(s)||revision!==listRevision)return false;page=null;readState='error';readError=t(error.status===403?'denied':error.status===404?'cardError':error.status===409?'cardError':'error');render();return false}finally{if(flight===token)flight=null}})();flight=token;return token.promise}
function ensureCard(){return window.tenantContactsBridge.ensureCard()}
function cardCurrent(token){return !bindingProblem()&&card===token&&token.revision===cardRevision&&current(token.scope)&&ownedCard()}
function cardShell(row,push,legacyDealId){if(!checkBinding()||push&&!writeCardRoute(row,legacyDealId))return null;const modal=ensureCard(),token={historyContext:window.tenantCrmSyncHistory?.capture(),revision:++cardRevision,scope:scope(),row,legacyDealId,opener:document.activeElement,route:location.href,tab:'general'};card=token;modal.dataset.contactsDirectoryOwner=String(token.revision);modal.dataset.type=row.kind==='native_contact'?'contact':'contact_history';modal.dataset.id=row.id||'';modal.classList.add('show');$('nativeEntityTitle').textContent=row.display_name||row.contact_name||row.lead_name||t('title');$('nativeEntityBody').innerHTML='<p id="contactsCardStatus" role="status">'+esc(t('loading'))+'</p>';modal.querySelector('[data-native-card-edit]').hidden=true;modal.querySelector('[data-native-card-archive]').hidden=true;return token}
function closeCard(){if(!ownedCard())return;const token=card,modal=$('nativeEntityCard');routeRevision++;cardRevision++;card=null;modal.classList.remove('show');$('nativeEntityBody').replaceChildren();$('nativeEntityTitle').textContent='';delete modal.dataset.contactsDirectoryOwner;if(history.state?.contactsCard){history.back()}else{const url=new URL(location.href);for(const key of ['contact_id','contacts_entry','deal_id','contacts_tenant'])url.searchParams.delete(key);const historyState={...history.state,contactsCard:false};delete historyState.contactsTenant;history.replaceState(historyState,'',url)}if(current(token.scope)&&visible()){const button=[...$('customersList').querySelectorAll('[data-contact-open]')].find(node=>node.dataset.contactOpen===token.row.key);const target=token.opener?.isConnected?token.opener:button||$('contactsTitle');target?.focus({preventScroll:true})}}
